// The bank's seven voice services (service contract of 1 Oct 2026) as a pure table lookup over
// test-environment/test-customers.json (src/data.js, generated by tools/make-data.mjs).
//
//   POST /voice/v1/cards.list             data.customerNo
//   POST /voice/v1/cards.balance          data.cardNumber
//   POST /voice/v1/statement.week.get     data.cardNumber
//   POST /voice/v1/statement.week.decide  data.cardNumber, then String(data.newStatementWeek)
//   POST /voice/v1/statement.week.change  data.cardNumber, then String(data.newStatementWeek)
//   POST /voice/v1/contact.email.get      data.customerNo
//   POST /voice/v1/statement.pdf.send     data.customerNo
//   POST /oauth2/token                    {"access_token":"test-token","token_type":"Bearer","expires_in":1800}
//
// A request the file has an entry for gets exactly that entry's `response` with its `http` status
// (after `delaySeconds`, when the entry has one). Everything else gets the contract's error body.
// Only the request's `data` decides (fields at the top level are accepted when there is no `data`);
// token, headers, `call` and `aiFlow` are never checked. Nothing is stateful: week changes and PDF
// sends are recorded for /__state only and never change an answer.
import DATA from './data.js';
import { digits, fold, json } from './util.js';
import { record } from './state.js';

// The contract's base path. The worker also accepts every path without it.
export const BASE = '/voice/v1';

export const customers = DATA.customers;

export const settings = {
  // Multiplies an entry's delaySeconds (1 = the real 12 s). Tests set it small.
  DELAY_SCALE: 1,
  ERROR_ORIGIN: 'ivr-gateway-test:ivr-channel-v0',
};

const EXC = 'com.freyabank.ivrgateway.ivrchannel.rest.exception.';

// ---------- Contract error body (section 4): result only, no data ----------

export const newGuid = () => crypto.randomUUID().replace(/-/g, '');

// The worker's own errors arrive with generic codes; map them to the contract's.
const GENERIC = {
  bad_json: { code: 'INVALID_ARGUMENTS_ERROR', type: 'ERROR', rootCause: `${EXC}InvalidArgumentsException` },
  missing_fields: { code: 'INVALID_ARGUMENTS_ERROR', type: 'ERROR', rootCause: `${EXC}InvalidArgumentsException` },
  not_found: { code: 'NOT_FOUND', type: 'ERROR', rootCause: `${EXC}NotFoundException` },
  method_not_allowed: { code: 'METHOD_NOT_ALLOWED', type: 'ERROR', rootCause: `${EXC}MethodNotAllowedException` },
  internal_error: { code: 'FBE00099', type: 'ERROR', rootCause: 'TechnicalError', message: 'Teknik hata: ABORTED: ' },
  state_unavailable: { code: 'FBE00099', type: 'ERROR', rootCause: 'TechnicalError', message: 'Teknik hata: ABORTED: ' },
};

// errorBody(status, code, { message, type, rootCause }): used by the handlers below and by the
// worker for its own errors (bad JSON 400, unknown path 404, 405, 500).
export function errorBody(status, code, extra = {}) {
  const g = GENERIC[code] ?? {};
  const c = g.code ?? code;
  const message = g.message ?? extra.message ?? c;
  const guid = newGuid();
  return {
    result: {
      guid,
      returnCode: c,
      messageText: message,
      code: c,
      message,
      type: extra.type ?? g.type ?? (status >= 500 || status === 400 ? 'ERROR' : 'WARNING'),
      details: {
        guid,
        rootCause: extra.rootCause ?? (g.code === 'FBE00099' && extra.message ? `MockError: ${extra.message}` : g.rootCause) ?? null,
        errorOrigin: settings.ERROR_ORIGIN,
      },
    },
  };
}

const fail = (status, code, type, message, rootCause) =>
  json(errorBody(status, code, { type, message, rootCause }), status);
// 400 for a missing/empty field, and for "not in the file" on services without a 404 (contract 6).
const invalid = (message) => fail(400, 'INVALID_ARGUMENTS_ERROR', 'ERROR', message, `${EXC}InvalidArgumentsException`);
const notFound = (code, message) => fail(404, code, 'WARNING', message, `${EXC}NotFoundException`);

// ---------- Indexes over the file ----------

const CARD_SERVICES = ['cards.balance', 'statement.week.get', 'statement.week.decide', 'statement.week.change'];
const byCustomer = new Map(); // digits of customerNo -> customer
const byCard = Object.fromEntries(CARD_SERVICES.map((s) => [s, new Map()])); // service -> card -> entry | {week: entry}
const owner = new Map(); // masked card -> customerNo
for (const c of customers) {
  byCustomer.set(digits(c.customerNo), c);
  for (const s of CARD_SERVICES) {
    for (const [card, v] of Object.entries(c.services?.[s] ?? {})) {
      byCard[s].set(card, v);
      if (!owner.has(card)) owner.set(card, c.customerNo);
    }
  }
}
const allCards = [...owner.keys()];
const cardDigits = new Map(allCards.map((k) => [k, { f6: k.slice(0, 6), f4: k.slice(0, 4), l4: k.slice(-4) }]));

// ---------- Input helpers ----------

const isObj = (v) => v != null && typeof v === 'object' && !Array.isArray(v);
// An unfilled placeholder ("{{customerNumber}}", "%7B%7B...", "540000******{{last4}}"): an ordinary
// unknown value (not in the file -> the service's 404/400), logged as template_warning.
export const isTemplate = (v) => typeof v === 'string' && /\{\{|%7b%7b/i.test(v);
const isEmpty = (v) => v == null || (typeof v === 'string' && v.trim() === '') || (typeof v === 'object' && Object.keys(v).length === 0);

// The service fields: body.data (an object, or a JSON string of one), over top-level fields
// (lenient when `data` is missing), over the query. `call` is never read.
function fieldsOf({ body, query }) {
  const top = isObj(body) ? { ...body } : {};
  let data = top.data;
  delete top.data;
  delete top.call;
  if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch { /* not JSON: ignored */ }
  }
  return { ...(query ?? {}), ...top, ...(isObj(data) ? data : {}) };
}

// template_warning naming the fields that arrived as an unfilled placeholder (call is not read).
function templateNote(f, note) {
  const keys = Object.keys(f).filter((k) => isTemplate(f[k]));
  if (keys.length) note({ template_warning: `unfilled placeholder in ${keys.join(', ')}` });
}

// Other spellings a tool might use; served, with a field_warning in the log.
const ALIASES = {
  customerNo: ['customerNumber', 'customer_no', 'customerId', 'customer_id'],
  cardNumber: ['cardNo', 'card_number'],
  newStatementWeek: ['statementWeek', 'week'],
};
function field(f, name, note) {
  if (!isEmpty(f[name])) return f[name];
  for (const a of ALIASES[name] ?? []) {
    if (!isEmpty(f[a])) {
      note({ field_warning: `${name} sent as ${a}` });
      return f[a];
    }
  }
  return f[name];
}

// customerNo as string or number, spaces trimmed: its digits ("90000001", 90000001, " 9000 0001 ").
function customerOf(v) {
  if (isTemplate(v)) return { c: null, how: 'template' };
  const d = digits(String(v).trim().replace(/[.,]0+$/, ''));
  return { c: byCustomer.get(d) ?? null, how: 'digits' };
}

// The file's masked card number for what was sent. Order: exact key; normalised (spaces, dashes,
// dots out; X/x/•/●/# masks of any count as *); first 6 + last 4 when >= 10 digits were sent
// (a full 16-digit number too); first 4 + last 4 (the cards.balance masking 5400********1234)
// when exactly one card in the file has them; never the last 4 alone.
// Returns { card, how } or { card: null, how } ('ambiguous' / 'no_match').
export function resolveCard(v) {
  if (isTemplate(v)) return { card: null, how: 'template' };
  const s = String(v ?? '').trim();
  if (owner.has(s)) return { card: s, how: 'exact' };
  const t = s.replace(/[\s\-.]/g, '').replace(/[xX•●·∙#]/g, '*');
  const m = /^(\d{6})\*+(\d{4})$/.exec(t);
  if (m && owner.has(`${m[1]}******${m[2]}`)) return { card: `${m[1]}******${m[2]}`, how: 'normalised' };
  const d = digits(s);
  if (d.length >= 10) {
    const k = `${d.slice(0, 6)}******${d.slice(-4)}`;
    if (owner.has(k)) return { card: k, how: 'first6+last4' };
  }
  const unique = (pred, how) => {
    const hits = allCards.filter((k) => pred(cardDigits.get(k)));
    if (hits.length === 1) return { card: hits[0], how };
    return hits.length > 1 ? { card: null, how: 'ambiguous', candidates: hits } : null;
  };
  // Never by the last 4 alone: a made-up number ending like some card would get another customer's answer.
  let r = null;
  if (d.length >= 8) r = unique((x) => x.f4 === d.slice(0, 4) && x.l4 === d.slice(-4), 'first4+last4');
  return r ?? { card: null, how: 'no_match' };
}

// A week as a word (folded): the text may hold only one of these plus filler words.
const WEEK_WORDS = {
  bir: 1, birinci: 1, ilk: 1, first: 1, one: 1, iki: 2, ikinci: 2, second: 2, two: 2,
  uc: 3, ucuncu: 3, third: 3, three: 3, dort: 4, dorduncu: 4, fourth: 4, four: 4,
};
const WEEK_FILLER = new Set(['hafta', 'haftasi', 'haftaya', 'haftayi', 'week', 'the', 'of', 'ayin']);

// "3", 3, " 3 ", "3.0", "03", "3. hafta" -> "3"; "üçüncü", "üçüncü hafta", "third" -> "3" (with a
// field_warning); anything else (a placeholder, "bir sonraki hafta", two weeks named): the text as is.
function weekOf(v, note) {
  const s = String(v).trim();
  if (isTemplate(v)) return s;
  const m = /\d+/.exec(s);
  if (m) return String(Number(m[0]));
  const words = fold(s).split(/[^a-z]+/).filter(Boolean);
  const weeks = new Set(words.filter((w) => Object.hasOwn(WEEK_WORDS, w)).map((w) => WEEK_WORDS[w]));
  if (weeks.size !== 1 || !words.every((w) => Object.hasOwn(WEEK_WORDS, w) || WEEK_FILLER.has(w))) return s;
  const [week] = weeks;
  note({ field_warning: `newStatementWeek sent as word (${JSON.stringify(v)} -> ${week})` });
  return String(week);
}

// ---------- Answers ----------

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// The entry's body and status exactly; its delay first. (`yanit`/`gecikmeSaniye` are the names
// the file's own description uses; the entries use `response`/`delaySeconds`. Both are read.)
async function serve(entry, note, matched) {
  const delay = entry.delaySeconds ?? entry.gecikmeSaniye;
  note({ matched, ...(delay && { delaySeconds: delay }) });
  if (delay) await sleep(delay * 1000 * settings.DELAY_SCALE);
  return json(entry.response ?? entry.yanit, entry.http);
}

function cardOrNote(f, note) {
  const r = resolveCard(f.cardNumber);
  if (r.how !== 'exact') note({ card_match: r.how, ...(r.candidates && { candidates: r.candidates }), card_sent: f.cardNumber });
  return r.card;
}

function cardService(service, notFoundCode, notFoundMessage) {
  return async ({ note, ...ctx }) => {
    const f = fieldsOf(ctx);
    templateNote(f, note);
    f.cardNumber = field(f, 'cardNumber', note);
    if (isEmpty(f.cardNumber)) return invalid('card number cannot be empty');
    const card = cardOrNote(f, note);
    const entry = card && byCard[service].get(card);
    if (!entry) return notFound(notFoundCode, notFoundMessage);
    return serve(entry, note, { customerNo: owner.get(card), cardNumber: card });
  };
}

function weekService(service) {
  return async ({ note, ...ctx }) => {
    const f = fieldsOf(ctx);
    templateNote(f, note);
    f.cardNumber = field(f, 'cardNumber', note);
    f.newStatementWeek = field(f, 'newStatementWeek', note);
    if (isEmpty(f.cardNumber)) return invalid('card number cannot be empty');
    if (isEmpty(f.newStatementWeek)) return invalid('newStatementWeek cannot be empty');
    if (isEmpty(f.statementDay)) note({ field_warning: 'statementDay missing (the contract requires it; served anyway)' });
    const card = cardOrNote(f, note);
    const weeks = card && byCard[service].get(card);
    if (!weeks) return invalid('card number is not valid: card not found');
    const week = weekOf(f.newStatementWeek, note);
    const current = byCard['statement.week.get'].get(card)?.response?.data;
    if (current && !isEmpty(f.statementDay) && String(f.statementDay).trim() !== String(current.statementDay)) {
      note({ field_warning: `statementDay ${f.statementDay}, the card's is ${current.statementDay}` });
    }
    const entry = Object.hasOwn(weeks, week) ? weeks[week] : null; // not "constructor" etc.
    if (!entry) {
      if (!/^[1-4]$/.test(week)) return invalid(`newStatementWeek must be 1, 2, 3 or 4 (got ${JSON.stringify(f.newStatementWeek)})`);
      return invalid(`newStatementWeek ${week} is the card's current statement week`);
    }
    if (service === 'statement.week.change') {
      record('week_change', owner.get(card), { cardNumber: card, newStatementWeek: week, http: entry.http });
    }
    return serve(entry, note, { customerNo: owner.get(card), cardNumber: card, newStatementWeek: week });
  };
}

function customerService(service, onUnknown, check) {
  return async ({ note, ...ctx }) => {
    const f = fieldsOf(ctx);
    templateNote(f, note);
    f.customerNo = field(f, 'customerNo', note);
    if (isEmpty(f.customerNo)) return invalid('customer number cannot be empty');
    const bad = check?.(f, note);
    if (bad) return bad;
    const { c, how } = customerOf(f.customerNo);
    if (how === 'template') note({ customer_match: 'template' });
    const entry = c?.services?.[service];
    const res = entry ? null : onUnknown();
    if (service === 'statement.pdf.send') pdfNotes(f, c, entry, note);
    return res ?? serve(entry, note, { customerNo: c.customerNo });
  };
}

// statement.pdf.send is looked up by customerNo only (test-customers.md). The other fields are
// checked for the log only: missing ones, a card of another customer, an address that is not the
// registered one, a date that is not the card's issued statement.
function pdfNotes(f, c, entry, note) {
  const warn = [];
  for (const k of ['cardNumber', 'currencyType', 'statementDate', 'emailAddress']) if (isEmpty(f[k])) warn.push(`${k} missing`);
  const card = isEmpty(f.cardNumber) ? null : resolveCard(f.cardNumber).card;
  if (c && card && owner.get(card) !== c.customerNo) warn.push(`cardNumber ${f.cardNumber} is not this customer's`);
  if (!isEmpty(f.cardNumber) && !card) warn.push(`cardNumber ${f.cardNumber} not in the file`);
  const registered = c?.services?.['contact.email.get']?.response?.data?.ibanEmail;
  if (!isEmpty(f.emailAddress) && registered != null && String(f.emailAddress).trim().toLowerCase() !== registered.toLowerCase()) {
    warn.push(`emailAddress ${f.emailAddress} is not the registered ${JSON.stringify(registered)}`);
  }
  const issued = card && byCard['cards.balance'].get(card)?.response?.data?.statementDate;
  if (issued && !isEmpty(f.statementDate) && String(f.statementDate).trim() !== issued) {
    warn.push(`statementDate ${f.statementDate}, the card's issued statement is ${issued}`);
  }
  if (!isEmpty(f.currencyType) && !['TL', 'USD', 'EUR', 'GBP'].includes(String(f.currencyType).trim())) {
    warn.push(`currencyType ${f.currencyType} is not TL/USD/EUR/GBP`);
  }
  if (warn.length) note({ field_warning: warn.join('; ') });
  record('pdf_send', c?.customerNo ?? f.customerNo, {
    cardNumber: f.cardNumber ?? null, currencyType: f.currencyType ?? null, statementDate: f.statementDate ?? null,
    emailAddress: f.emailAddress ?? null, http: entry?.http ?? 404,
  });
}

// contact.email.get: intAddressInfoType present but empty is a 400 (contract 5.6); absent is served.
function addressTypeCheck(f, note) {
  if (!('intAddressInfoType' in f)) {
    note({ field_warning: 'intAddressInfoType missing (served anyway)' });
    return null;
  }
  return isEmpty(f.intAddressInfoType) ? invalid('intAddressInfoType cannot be empty') : null;
}

export const routes = [
  { method: 'POST', path: '/cards.list',
    handler: customerService('cards.list', () => notFound('FB_IVR_CHANNEL_102', 'Müşteriye ait geçerli kart bilgisi bulunamadı.')) },
  { method: 'POST', path: '/cards.balance',
    handler: cardService('cards.balance', 'FB_IVR_CHANNEL_120', 'Kart bakiye servisi hatası: kart bulunamadı') },
  { method: 'POST', path: '/statement.week.get',
    handler: cardService('statement.week.get', 'FB_IVR_CHANNEL_121', 'Hesap kesim haftası servisi hatası: kart bulunamadı') },
  { method: 'POST', path: '/statement.week.decide', handler: weekService('statement.week.decide') },
  { method: 'POST', path: '/statement.week.change', handler: weekService('statement.week.change') },
  { method: 'POST', path: '/contact.email.get',
    handler: customerService('contact.email.get', () => invalid('customer number is not valid: customer not found'), addressTypeCheck) },
  { method: 'POST', path: '/statement.pdf.send',
    handler: customerService('statement.pdf.send', () => notFound('FB_IVR_CHANNEL_107', 'Pdf dokümanı bulunamadı')) },
  // Contract section 2. Form or JSON body, nothing checked.
  { method: 'POST', path: '/oauth2/token', root: true, handler: () => ({ access_token: 'test-token', token_type: 'Bearer', expires_in: 1800 }) },
];
